INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-10-slovakia-faq-penalties-published', '2026-03-10', '2026-03', 'Slovakia''s Financial Administration has published a detailed FAQ document clarifying the mechanics of e-Faktúra reporting, including a 5-day reporting window and penalties of up to €10,000 for missing or late data.', '<h3>🇸🇰 Financial Administration publishes detailed e-Faktúra FAQ, covering penalties and reporting timing</h3>
<p>Slovakia''s Financial Administration has published a detailed FAQ document setting out exactly how e-Faktúra reporting is meant to work in practice, running to dozens of worked examples rather than staying at a high level. One useful, specific clarification: once your contracted Digital Postman receives an invoice, you have 5 days to report the data from it to the tax authority — but this reporting happens automatically through your Digital Postman, not as a manual step businesses need to perform themselves.</p>
<p>The FAQ is also direct about the consequences of getting this wrong: failing to report invoice data, reporting it incorrectly, or reporting it after the deadline can result in a penalty of up to €10,000. The document also confirms that international e-invoicing — covering cross-border transactions — remains planned for 2030, well after the January 2027 domestic mandate, and separately addresses G2G (government-to-government) invoicing scenarios, including how to proceed when one party in such a transaction doesn''t have a standard business tax ID.</p>
<p><strong>What this means for your team:</strong> the automatic-reporting detail is worth confirming directly with whichever Digital Postman you''re planning to use — "automatic" should mean your team isn''t manually tracking the 5-day window, but it''s worth verifying this is genuinely how your specific provider''s service works before assuming it, rather than discovering a gap only once a real penalty is at stake.</p>', 'https://www.financnasprava.sk/sk/podnikatelia/dane/dan-z-pridanej-hodnoty/e-faktura', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-10-slovakia-faq-penalties-published', id FROM countries WHERE name_en = 'Slovakia';
