INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-26-slovakia-national-conference', '2026-05-26', '2026-05', 'The Financial Directorate of the Slovak Republic held a national conference on e-Faktúra for businesses, accountants, and advisers, part of a wider government outreach push ahead of the January 2027 mandate.', '<h3>🇸🇰 Financial Directorate holds national e-Faktúra conference for businesses and advisers</h3>
<p>The Financial Directorate of the Slovak Republic held a conference this May specifically aimed at the professional community — businesses, accountants, and tax advisers — framing e-Faktúra as a key tool in the broader digitalisation of Slovak business, rather than purely a compliance exercise. It''s part of a wider, ongoing outreach effort: the Financial Administration has also been running webinars through the year covering practical questions as they come up, alongside the FAQ documentation already published.</p>
<p>This kind of direct, sustained outreach from the tax authority itself is worth reading as a signal in its own right: it suggests the government is treating general market awareness and preparedness — not just the underlying technical infrastructure — as a genuine risk to manage ahead of January 2027, rather than assuming businesses will simply find their own way to compliance once accredited Digital Postman providers are in place.</p>
<p><strong>What this means for your team:</strong> if your tax or finance team hasn''t yet engaged with any of the Financial Administration''s own webinars, FAQ material, or outreach sessions, this is a genuine, direct line to the source rather than relying solely on third-party summaries — worth using given how much of Slovakia''s model puts compliance responsibility on correctly understanding your own obligations, not on a central authority validating things for you as you go.</p>', 'https://www.financnasprava.sk/sk/podnikatelia/dane/dan-z-pridanej-hodnoty/e-faktura', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-26-slovakia-national-conference', id FROM countries WHERE name_en = 'Slovakia';
