INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-24-spain-royal-decree-approved', '2026-03-24', '2026-03', 'Spain''s Council of Ministers approved Royal Decree 238/2026 on 24 March 2026, formally implementing the Crea y Crece B2B e-invoicing mandate, with reducing the country''s notoriously long average payment periods cited as a key motivation.', '<h3>🇪🇸 Spain formally approves its Crea y Crece B2B e-invoicing mandate</h3>
<p>Spain''s Council of Ministers approved Royal Decree 238/2026 on 24 March, formally implementing the long-anticipated B2B e-invoicing mandate under the Crea y Crece law — a decree requiring structured e-invoices, invoice status reporting, and interoperable exchange platforms, while delegating the detailed technical specifications to a separate Ministerial Order still to come. This is a genuinely significant milestone: Crea y Crece has existed as a law since 2022, but this Royal Decree is what actually gives it operative teeth.</p>
<p>The government''s own official communication is unusually direct about the underlying motivation: Spain has one of the longest average invoice payment periods in the European Union, at around 80 days — well above the 60-day maximum set by the Late Payment Law and well above the EU average. Real-time invoice status reporting (acceptance, rejection, or payment) is intended to make these delays visible and harder to quietly tolerate, not just to close a VAT compliance gap.</p>
<p><strong>What this means for your team:</strong> the Royal Decree formalises the mandate''s existence, but the operative dates and full technical detail depend on the Ministerial Order that follows it — worth tracking as a distinct, separate milestone rather than assuming this decree alone starts any clock. Businesses with genuinely poor payment-timeliness practices have a direct reason to treat this as more than a technical filing exercise, given the reporting mechanism is explicitly designed to surface exactly that kind of delay.</p>', 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-24-spain-royal-decree-approved', id FROM countries WHERE name_en = 'Spain';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-24-spain-royal-decree-approved', 'en', 'Spain formally approves its Crea y Crece B2B e-invoicing mandate', 'Spain''s Council of Ministers approved Royal Decree 238/2026 on 24 March 2026, formally implementing the Crea y Crece B2B e-invoicing mandate, with reducing the country''s notoriously long average payment periods cited as a key motivation.', '<h3>🇪🇸 Spain formally approves its Crea y Crece B2B e-invoicing mandate</h3>
<p>Spain''s Council of Ministers approved Royal Decree 238/2026 on 24 March, formally implementing the long-anticipated B2B e-invoicing mandate under the Crea y Crece law — a decree requiring structured e-invoices, invoice status reporting, and interoperable exchange platforms, while delegating the detailed technical specifications to a separate Ministerial Order still to come. This is a genuinely significant milestone: Crea y Crece has existed as a law since 2022, but this Royal Decree is what actually gives it operative teeth.</p>
<p>The government''s own official communication is unusually direct about the underlying motivation: Spain has one of the longest average invoice payment periods in the European Union, at around 80 days — well above the 60-day maximum set by the Late Payment Law and well above the EU average. Real-time invoice status reporting (acceptance, rejection, or payment) is intended to make these delays visible and harder to quietly tolerate, not just to close a VAT compliance gap.</p>
<p><strong>What this means for your team:</strong> the Royal Decree formalises the mandate''s existence, but the operative dates and full technical detail depend on the Ministerial Order that follows it — worth tracking as a distinct, separate milestone rather than assuming this decree alone starts any clock. Businesses with genuinely poor payment-timeliness practices have a direct reason to treat this as more than a technical filing exercise, given the reporting mechanism is explicitly designed to surface exactly that kind of delay.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-15-spain-aeat-exchange-guidance', '2026-05-15', '2026-05', 'AEAT has issued technical guidance clarifying that businesses can exchange Crea y Crece e-invoices via private platforms or the government''s own public solution — with a 4-day invoice-status reporting obligation applying either way.', '<h3>🇪🇸 AEAT clarifies exchange options: private platforms or a direct state platform</h3>
<p>AEAT has issued technical guidance clarifying how businesses will actually exchange e-invoices once the Crea y Crece mandate takes effect: a choice between a hybrid private-platform network or direct use of the government''s own Public Electronic Invoicing Solution (SPFE). This mirrors a pattern seen in a few other markets — a genuine choice of infrastructure rather than a single mandatory government route — but with one important catch specific to Spain''s model.</p>
<p>Businesses choosing to exchange invoices through a private platform must still simultaneously submit a "faithful copy" (copia fiel) of every invoice to the SPFE. In other words, opting for a private platform doesn''t mean opting out of the state platform entirely — it adds a parallel submission step rather than replacing it. Separately, whichever route is used, recipients must report an invoice''s status — acceptance, rejection, or full or partial payment — to AEAT within 4 calendar days of the transaction, a genuinely tight window that''s intended to work alongside the existing SII real-time reporting regime already in place for large taxpayers since 2017.</p>
<p><strong>What this means for your team:</strong> don''t assume that choosing a private platform simplifies your reporting obligations — the copia fiel requirement means you''re effectively integrating with two systems either way, not one. The 4-day status-reporting window is tight enough that it''s worth confirming now whether your existing accounts receivable/payable workflow can realistically produce an accurate status within that timeframe, rather than discovering the gap once real transaction volume is flowing through the system.</p>', 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-15-spain-aeat-exchange-guidance', id FROM countries WHERE name_en = 'Spain';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-15-spain-aeat-exchange-guidance', 'en', 'AEAT clarifies exchange options: private platforms or a direct state platform', 'AEAT has issued technical guidance clarifying that businesses can exchange Crea y Crece e-invoices via private platforms or the government''s own public solution — with a 4-day invoice-status reporting obligation applying either way.', '<h3>🇪🇸 AEAT clarifies exchange options: private platforms or a direct state platform</h3>
<p>AEAT has issued technical guidance clarifying how businesses will actually exchange e-invoices once the Crea y Crece mandate takes effect: a choice between a hybrid private-platform network or direct use of the government''s own Public Electronic Invoicing Solution (SPFE). This mirrors a pattern seen in a few other markets — a genuine choice of infrastructure rather than a single mandatory government route — but with one important catch specific to Spain''s model.</p>
<p>Businesses choosing to exchange invoices through a private platform must still simultaneously submit a "faithful copy" (copia fiel) of every invoice to the SPFE. In other words, opting for a private platform doesn''t mean opting out of the state platform entirely — it adds a parallel submission step rather than replacing it. Separately, whichever route is used, recipients must report an invoice''s status — acceptance, rejection, or full or partial payment — to AEAT within 4 calendar days of the transaction, a genuinely tight window that''s intended to work alongside the existing SII real-time reporting regime already in place for large taxpayers since 2017.</p>
<p><strong>What this means for your team:</strong> don''t assume that choosing a private platform simplifies your reporting obligations — the copia fiel requirement means you''re effectively integrating with two systems either way, not one. The 4-day status-reporting window is tight enough that it''s worth confirming now whether your existing accounts receivable/payable workflow can realistically produce an accurate status within that timeframe, rather than discovering the gap once real transaction volume is flowing through the system.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-20-spain-two-track-timeline-clarified', '2026-06-20', '2026-06', 'With two parallel Spanish obligations now in motion on different timelines, it''s worth being precise about which is which — VERI*FACTU governs certified invoicing software, while Crea y Crece is the actual B2B e-invoicing mandate, and confusing the two risks planning against the wrong date.', '<h3>🇪🇸 Spain''s two-track mandate, untangled: VERI*FACTU and Crea y Crece are not the same deadline</h3>
<p>Spain is running two distinct, overlapping compliance obligations at once, and conflating them is an easy, genuinely consequential mistake. VERI*FACTU — following a one-year delay confirmed by Real Decreto-ley 15/2025 in December 2025 — governs the certified invoicing software businesses use, and is now expected to apply from 1 January 2027 for companies subject to corporate tax and permanent establishments, and from 1 July 2027 for other covered persons, primarily the self-employed. It''s fundamentally about software certification and invoice integrity, not the invoice exchange mandate itself.</p>
<p>Crea y Crece is the separate, actual B2B e-invoicing mandate, and it runs on its own, later timeline: 1 October 2027 for large companies with turnover above €8 million, and 1 October 2028 for everyone else. As of mid-2026, the Ministerial Order that would formally activate these exact dates remains pending — the expected dates have solidified in official communications, but the final legal trigger hasn''t yet been published, which is worth knowing rather than treating either date as entirely locked in.</p>
<p><strong>What this means for your team:</strong> if your business is planning around "Spain''s e-invoicing deadline" as a single date, split that planning into two genuinely separate workstreams — invoicing software certification (VERI*FACTU) and invoice exchange infrastructure (Crea y Crece) — since they apply to different things, on different timelines, and getting one compliant doesn''t mean anything about the other. Given the Ministerial Order is still pending, it''s also worth checking back periodically rather than treating the current expected dates as final.</p>', 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-20-spain-two-track-timeline-clarified', id FROM countries WHERE name_en = 'Spain';
